 		_, _ = io.WriteString(hash, value)
 		_, _ = io.WriteString(hash, "\x00")
 	}
 	writePart(searchSnapshotCacheVersion)
 	writePart(absRepo)
 	writePart(repositoryKey)
 	writePart(providerVersion)
 	writePart(tree)
 	writePart(string(options.Profile))
